"""
WebSocket notification server.

Accepts WebSocket connections, assigns each client a unique ID, supports
broadcast / direct / system messages, and exposes a health endpoint both as a
WebSocket 'system' message and via a plain HTTP listener running in a separate
thread (thread-safety is guaranteed by a threading.Lock around the registry).

Channels: clients may subscribe/unsubscribe to named channels. Messages that
carry a 'channel' field are routed only to the subscribers of that channel;
messages without a channel broadcast to every connected client. The HTTP
listener also exposes GET /channels and GET /channels/{name}/subscribers.
"""

import asyncio
import json
import os
import threading
import uuid
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlparse

from websockets.asyncio.server import serve

WS_HOST = os.environ.get("WS_HOST", "127.0.0.1")
WS_PORT = int(os.environ.get("WS_PORT", "8765"))
HEALTH_HOST = os.environ.get("HEALTH_HOST", "127.0.0.1")
HEALTH_PORT = int(os.environ.get("HEALTH_PORT", "8766"))

SUPPORTED_TYPES = ("broadcast", "direct", "system", "subscribe", "unsubscribe")


def make_message(msg_type: str, payload: dict) -> dict:
    """Build a message in the canonical wire format."""
    return {
        "type": msg_type,
        "payload": payload,
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }


class ClientRegistry:
    """Thread-safe registry of connected clients (client_id -> connection).

    Also tracks channel subscriptions (channel -> set of client_ids). Every
    mutation is guarded by a threading.Lock so the separate HTTP health thread
    can safely observe and coordinate with the async world.
    """

    def __init__(self):
        self._clients = {}
        self._subscriptions = {}
        self._lock = threading.Lock()

    def add(self, connection) -> str:
        client_id = uuid.uuid4().hex
        with self._lock:
            self._clients[client_id] = connection
        return client_id

    def remove(self, client_id: str) -> None:
        with self._lock:
            self._clients.pop(client_id, None)
            for channel, subscribers in list(self._subscriptions.items()):
                subscribers.discard(client_id)
                if not subscribers:
                    del self._subscriptions[channel]

    def get(self, client_id: str):
        with self._lock:
            return self._clients.get(client_id)

    def snapshot(self) -> dict:
        with self._lock:
            return dict(self._clients)

    def subscribe(self, client_id: str, channel: str) -> None:
        with self._lock:
            self._subscriptions.setdefault(channel, set()).add(client_id)

    def unsubscribe(self, client_id: str, channel: str) -> None:
        with self._lock:
            subscribers = self._subscriptions.get(channel)
            if subscribers is not None:
                subscribers.discard(client_id)
                if not subscribers:
                    del self._subscriptions[channel]

    def subscribers_of(self, channel: str) -> set:
        with self._lock:
            return set(self._subscriptions.get(channel, ()))

    def channels_snapshot(self) -> dict:
        with self._lock:
            return {channel: set(ids) for channel, ids in self._subscriptions.items()}

    def __len__(self) -> int:
        with self._lock:
            return len(self._clients)


async def broadcast(registry: ClientRegistry, message: dict, exclude: str | None = None) -> None:
    """Broadcast to every connected client by iterating the registry and
    awaiting send() on each connection (websockets.broadcast is deprecated)."""
    for client_id, connection in registry.snapshot().items():
        if exclude is not None and client_id == exclude:
            continue
        try:
            await connection.send(json.dumps(message))
        except Exception:
            registry.remove(client_id)


async def broadcast_to_channel(
    registry: ClientRegistry, channel: str, message: dict, exclude: str | None = None
) -> None:
    """Deliver a message only to the clients subscribed to the given channel."""
    for client_id in registry.subscribers_of(channel):
        if exclude is not None and client_id == exclude:
            continue
        connection = registry.get(client_id)
        if connection is None:
            continue
        try:
            await connection.send(json.dumps(message))
        except Exception:
            registry.remove(client_id)


class NotificationServer:
    """Owns a ClientRegistry and drives the per-connection event loop."""

    def __init__(self, registry: ClientRegistry | None = None):
        self.registry = registry or ClientRegistry()

    async def handle(self, connection) -> None:
        client_id = self.registry.add(connection)
        try:
            await connection.send(
                json.dumps(
                    make_message("system", {"action": "connected", "client_id": client_id})
                )
            )
            async for raw in connection:
                await self._process(client_id, connection, raw)
        finally:
            self.registry.remove(client_id)

    async def _process(self, client_id: str, connection, raw: str) -> None:
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, TypeError):
            await connection.send(
                json.dumps(make_message("system", {"action": "error", "message": "invalid json"}))
            )
            return

        msg_type = data.get("type")
        payload = data.get("payload") or {}

        if msg_type == "system" and payload.get("action") == "health":
            await connection.send(
                json.dumps(
                    make_message("system", {"action": "health", "client_count": len(self.registry)})
                )
            )
        elif msg_type == "subscribe":
            channel = payload.get("channel") or data.get("channel")
            if channel:
                self.registry.subscribe(client_id, channel)
                await connection.send(
                    json.dumps(
                        make_message("system", {"action": "subscribed", "channel": channel})
                    )
                )
            else:
                await connection.send(
                    json.dumps(
                        make_message("system", {"action": "error", "message": "channel required"})
                    )
                )
        elif msg_type == "unsubscribe":
            channel = payload.get("channel") or data.get("channel")
            if channel:
                self.registry.unsubscribe(client_id, channel)
                await connection.send(
                    json.dumps(
                        make_message("system", {"action": "unsubscribed", "channel": channel})
                    )
                )
            else:
                await connection.send(
                    json.dumps(
                        make_message("system", {"action": "error", "message": "channel required"})
                    )
                )
        elif msg_type == "broadcast":
            channel = payload.get("channel") or data.get("channel")
            if channel:
                await broadcast_to_channel(
                    self.registry, channel, make_message("broadcast", payload)
                )
            else:
                await broadcast(self.registry, make_message("broadcast", payload))
        elif msg_type == "direct":
            target = payload.get("client_id")
            conn = self.registry.get(target)
            if conn is not None:
                await conn.send(json.dumps(make_message("direct", payload)))
            else:
                await connection.send(
                    json.dumps(
                        make_message("system", {"action": "error", "message": "client not found"})
                    )
                )
        else:
            await connection.send(
                json.dumps(make_message("system", {"action": "error", "message": "unsupported type"}))
            )


def _make_health_handler(registry: ClientRegistry):
    class HealthHandler(BaseHTTPRequestHandler):
        def do_GET(self):
            path = unquote(urlparse(self.path).path)
            if path == "/health":
                body = json.dumps({"client_count": len(registry)}).encode("utf-8")
            elif path == "/channels":
                channels = {
                    name: len(subscribers)
                    for name, subscribers in registry.channels_snapshot().items()
                }
                body = json.dumps({"channels": channels}).encode("utf-8")
            elif path.startswith("/channels/") and len(path) > len("/channels/"):
                rest = path[len("/channels/") :]
                name = None
                if rest.endswith("/subscribers"):
                    name = rest[: -len("/subscribers")]
                elif "/" not in rest:
                    name = rest
                if not name or "/" in name:
                    self.send_error(404)
                    return
                subscribers = sorted(registry.subscribers_of(name))
                body = json.dumps(
                    {"channel": name, "subscribers": subscribers}
                ).encode("utf-8")
            else:
                self.send_error(404)
                return
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format, *args):
            pass

    return HealthHandler


def start_health_server(registry: ClientRegistry, host: str = HEALTH_HOST, port: int = 0):
    """Run the HTTP health listener in a separate thread."""
    httpd = ThreadingHTTPServer((host, port), _make_health_handler(registry))
    thread = threading.Thread(target=httpd.serve_forever, daemon=True)
    thread.start()
    return httpd


def stop_health_server(httpd) -> None:
    httpd.shutdown()
    httpd.server_close()


async def start_ws_server(server: NotificationServer, host: str = WS_HOST, port: int = 0):
    """Start the WebSocket listener and return the underlying server object."""
    return await serve(server.handle, host, port)


async def main():
    server = NotificationServer()
    ws_server = await start_ws_server(server)
    httpd = start_health_server(server.registry)
    ws_port = ws_server.sockets[0].getsockname()[1]
    health_port = httpd.server_address[1]
    print(f"WebSocket listening on {WS_HOST}:{ws_port}")
    print(f"Health listening on {HEALTH_HOST}:{health_port}")
    try:
        await asyncio.Future()
    finally:
        ws_server.close()
        stop_health_server(httpd)


if __name__ == "__main__":
    asyncio.run(main())

"""Async WebSocket notification server backed by Redis and SQLite."""

from __future__ import annotations

import asyncio
import json
import os
import sqlite3
import threading
import uuid
from datetime import datetime, timedelta, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from abc import ABC, abstractmethod
from typing import Any
from urllib.parse import parse_qs, unquote, urlparse

from websockets.asyncio.server import ServerConnection, serve

try:
    from redis.asyncio import Redis
except ImportError:  # pragma: no cover - requirements install redis in production
    Redis = Any  # type: ignore[misc,assignment]


SUPPORTED_TYPES = {"broadcast", "direct", "system", "subscribe", "unsubscribe"}


def timestamp() -> str:
    return datetime.now(timezone.utc).isoformat()


class MessageStore:
    def __init__(self, database_url: str | None = None) -> None:
        value = database_url or os.getenv("DATABASE_URL", "sqlite:///:memory:")
        if value.startswith("sqlite:///"):
            path = value[10:]
        elif value.startswith("sqlite://"):
            path = value[9:]
        else:
            path = value
        self.path = path or ":memory:"
        self._lock = threading.Lock()
        self._connection: sqlite3.Connection | None = None

    def open(self) -> None:
        self._connection = sqlite3.connect(self.path, check_same_thread=False)
        self._connection.execute(
            "CREATE TABLE IF NOT EXISTS messages ("
            "id INTEGER PRIMARY KEY AUTOINCREMENT, channel TEXT, type TEXT NOT NULL, "
            "payload TEXT NOT NULL, timestamp TEXT NOT NULL)"
        )
        self._connection.commit()

    def close(self) -> None:
        if self._connection is not None:
            with self._lock:
                self._connection.close()
            self._connection = None

    def add(self, channel: str | None, message_type: str, payload: dict[str, Any], time: str) -> None:
        if self._connection is None:
            raise RuntimeError("message store is not open")
        with self._lock:
            self._connection.execute(
                "INSERT INTO messages(channel, type, payload, timestamp) VALUES (?, ?, ?, ?)",
                (channel, message_type, json.dumps(payload), time),
            )
            self._connection.commit()

    def list(self, limit: int, offset: int) -> list[dict[str, Any]]:
        return self._query(
            "SELECT id, channel, type, payload, timestamp FROM messages "
            "ORDER BY id LIMIT ? OFFSET ?", (limit, offset)
        )

    def history(self, channel: str, since: str | None, limit: int) -> tuple[list[dict[str, Any]], bool]:
        if self._connection is None:
            return [], False
        conditions = ["channel = ?"]
        parameters: list[Any] = [channel]
        if since is not None:
            conditions.append("timestamp >= ?")
            parameters.append(since)
        parameters.append(limit + 1)
        rows = self._query(
            "SELECT id, channel, type, payload, timestamp FROM messages WHERE "
            + " AND ".join(conditions) + " ORDER BY timestamp ASC, id ASC LIMIT ?",
            tuple(parameters),
        )
        return rows[:limit], len(rows) > limit

    def delete_older_than(self, cutoff: str) -> None:
        if self._connection is None:
            return
        with self._lock:
            self._connection.execute("DELETE FROM messages WHERE timestamp < ?", (cutoff,))
            self._connection.commit()

    def _query(self, query: str, parameters: tuple[Any, ...]) -> list[dict[str, Any]]:
        if self._connection is None:
            return []
        with self._lock:
            rows = self._connection.execute(query, parameters).fetchall()
        return [{"id": row[0], "channel": row[1], "type": row[2],
                 "payload": json.loads(row[3]), "timestamp": row[4]} for row in rows]


class _HealthHandler(BaseHTTPRequestHandler):
    server_version = "NotificationHealth/1.0"

    def do_GET(self) -> None:  # noqa: N802
        owner: NotificationServer = self.server.owner  # type: ignore[attr-defined]
        parsed = urlparse(self.path)
        path = parsed.path
        if path == "/health":
            body_data = {"connected_clients": owner.client_count}
        elif path == "/channels":
            body_data = {"channels": owner.channel_counts()}
        elif path == "/messages":
            query = parse_qs(parsed.query)
            try:
                limit = max(0, min(1000, int(query.get("limit", ["50"])[0])))
                offset = max(0, int(query.get("offset", ["0"])[0]))
            except ValueError:
                self.send_error(400, "limit and offset must be integers")
                return
            body_data = {"messages": owner.messages(limit, offset)}
        elif path == "/history":
            query = parse_qs(parsed.query)
            channel = query.get("channel", [""])[0]
            if not channel:
                self.send_error(400, "channel is required")
                return
            since = query.get("since", [None])[0]
            if since is not None:
                try:
                    datetime.fromisoformat(since.replace("Z", "+00:00"))
                except ValueError:
                    self.send_error(400, "since must be an ISO timestamp")
                    return
            try:
                limit = max(1, min(1000, int(query.get("limit", ["50"])[0])))
            except ValueError:
                self.send_error(400, "limit must be an integer")
                return
            messages, has_more = owner.history(channel, since, limit)
            body_data = {"messages": messages, "has_more": has_more}
        elif path.startswith("/channels/") and path.endswith("/subscribers"):
            channel = unquote(path[len("/channels/"):-len("/subscribers")])
            if not channel or "/" in channel:
                self.send_error(404)
                return
            body_data = {"subscribers": owner.channel_subscribers(channel)}
        else:
            self.send_error(404)
            return
        body = json.dumps(body_data).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, *_args: Any) -> None:
        return


class _HealthServer(ThreadingHTTPServer):
    def __init__(self, address: tuple[str, int], owner: "NotificationServer") -> None:
        self.owner = owner
        super().__init__(address, _HealthHandler)


class BaseTransport(ABC):
    """Transport contract used by the notification server."""

    def __init__(self, owner: "NotificationServer") -> None:
        self.owner = owner
        self.clients: dict[str, Any] = {}

    @abstractmethod
    async def on_connect(self, connection: Any) -> str:
        """Register a newly connected client and return its client id."""

    @abstractmethod
    async def on_disconnect(self, client_id: str) -> None:
        """Remove a client from the transport."""

    @abstractmethod
    async def send_message(self, client_id: str, message: str) -> None:
        """Send a serialized message to one client."""

    @abstractmethod
    async def broadcast(self, message: str, client_ids: list[str] | None = None) -> None:
        """Send a serialized message to selected clients, or all clients."""

    async def start(self, host: str, port: int) -> int:
        """Start listening and return the selected port."""
        raise NotImplementedError

    async def stop(self) -> None:
        """Stop listening and close connected clients."""


class WebSocketTransport(BaseTransport):
    """WebSocket implementation of the notification transport."""

    def __init__(self, owner: "NotificationServer") -> None:
        super().__init__(owner)
        self._server = None

    async def on_connect(self, connection: ServerConnection) -> str:
        client_id = str(uuid.uuid4())
        self.clients[client_id] = connection
        return client_id

    async def on_disconnect(self, client_id: str) -> None:
        self.clients.pop(client_id, None)

    async def send_message(self, client_id: str, message: str) -> None:
        connection = self.clients.get(client_id)
        if connection is not None:
            await connection.send(message)

    async def broadcast(self, message: str, client_ids: list[str] | None = None) -> None:
        ids = client_ids if client_ids is not None else list(self.clients)
        await asyncio.gather(*(self.send_message(client_id, message) for client_id in ids),
                             return_exceptions=True)

    async def start(self, host: str, port: int) -> int:
        self._server = await serve(self._handle_client, host, port)
        return self._server.sockets[0].getsockname()[1]

    async def stop(self) -> None:
        if self._server is not None:
            self._server.close()
            await self._server.wait_closed()
            self._server = None
        connections = list(self.clients.values())
        await asyncio.gather(*(client.close() for client in connections), return_exceptions=True)
        self.clients.clear()

    async def _handle_client(self, connection: ServerConnection) -> None:
        client_id = await self.on_connect(connection)
        await self.owner._on_client_connect(client_id)
        try:
            async for raw_message in connection:
                await self.owner._handle_message(client_id, raw_message)
        finally:
            await self.owner._on_client_disconnect(client_id)
            await self.on_disconnect(client_id)


class NotificationServer:
    """Manage notifications, with Redis distributing messages between instances."""

    redis_channel = "notifications:messages"

    def __init__(self, host: str = "127.0.0.1", websocket_port: int = 8765,
                 http_port: int = 8080, redis_url: str | None = None,
                 database_url: str | None = None, redis_client: Any = None,
                 transport: BaseTransport | None = None) -> None:
        self.host, self.websocket_port, self.http_port = host, websocket_port, http_port
        self.redis_url = redis_url if redis_url is not None else os.getenv("REDIS_URL")
        self.redis = redis_client
        self.store = MessageStore(database_url)
        self.registry_lock = threading.Lock()
        self.client_channels: dict[str, set[str]] = {}
        self.channels: dict[str, set[str]] = {}
        self.transport = transport or self._create_transport()
        self.clients = self.transport.clients
        self._health_server: _HealthServer | None = None
        self._health_thread: threading.Thread | None = None
        self._subscriber_task: asyncio.Task[None] | None = None
        self._redis_pubsub: Any = None
        self._instance_id = str(uuid.uuid4())
        self.rate_limit = max(0, int(os.getenv("RATE_LIMIT", "100")))
        self.message_ttl_days = max(0, float(os.getenv("MESSAGE_TTL_DAYS", "7")))
        self._local_rate_windows: dict[str, tuple[float, int]] = {}
        self._rate_lock = threading.Lock()
        self._cleanup_task: asyncio.Task[None] | None = None

    def _create_transport(self) -> BaseTransport:
        selected = os.getenv("TRANSPORT", "websocket").strip().lower()
        if selected in {"websocket", "ws"}:
            return WebSocketTransport(self)
        raise ValueError(f"unsupported transport: {selected}")

    @property
    def client_count(self) -> int:
        with self.registry_lock:
            return len(self.clients)

    def channel_counts(self) -> dict[str, int]:
        with self.registry_lock:
            return {name: len(users) for name, users in self.channels.items() if users}

    def channel_subscribers(self, channel: str) -> list[str]:
        with self.registry_lock:
            return sorted(self.channels.get(channel, set()))

    def messages(self, limit: int, offset: int) -> list[dict[str, Any]]:
        return self.store.list(limit, offset)

    def history(self, channel: str, since: str | None, limit: int) -> tuple[list[dict[str, Any]], bool]:
        return self.store.history(channel, since, limit)

    async def start(self) -> None:
        self.store.open()
        self._cleanup_task = asyncio.create_task(self._cleanup_loop())
        if self.redis is None and self.redis_url:
            self.redis = Redis.from_url(self.redis_url, decode_responses=True)
        if self.redis is not None:
            try:
                await self.redis.ping()
                self._redis_pubsub = self.redis.pubsub()
                await self._redis_pubsub.subscribe(self.redis_channel)
                self._subscriber_task = asyncio.create_task(self._consume_redis())
            except Exception:
                await self._close_redis()
        self.websocket_port = await self.transport.start(self.host, self.websocket_port)
        self._health_server = _HealthServer((self.host, self.http_port), self)
        self.http_port = self._health_server.server_address[1]
        self._health_thread = threading.Thread(target=self._health_server.serve_forever,
                                                name="notification-health", daemon=True)
        self._health_thread.start()

    async def stop(self) -> None:
        await self.transport.stop()
        if self._cleanup_task:
            self._cleanup_task.cancel()
            await asyncio.gather(self._cleanup_task, return_exceptions=True)
            self._cleanup_task = None
        if self._subscriber_task:
            self._subscriber_task.cancel()
            await asyncio.gather(self._subscriber_task, return_exceptions=True)
        await self._close_redis()
        with self.registry_lock:
            self.client_channels.clear(); self.channels.clear()
        if self._health_server is not None:
            self._health_server.shutdown(); self._health_server.server_close()
        if self._health_thread is not None:
            self._health_thread.join(timeout=2)
        self.store.close()

    async def _close_redis(self) -> None:
        if self._redis_pubsub is not None:
            await self._redis_pubsub.close()
            self._redis_pubsub = None
        if self.redis is not None and self.redis_url:
            await self.redis.aclose()
            self.redis = None

    async def _consume_redis(self) -> None:
        while True:
            item = await self._redis_pubsub.get_message(ignore_subscribe_messages=True, timeout=1.0)
            if item and item.get("data"):
                envelope = json.loads(item["data"])
                if envelope.get("origin") != self._instance_id:
                    await self._deliver(envelope["message"])
            await asyncio.sleep(0)

    async def _on_client_connect(self, client_id: str) -> None:
        with self.registry_lock:
            self.client_channels[client_id] = set()
        await self._save_client_state(client_id, "connected", set())
        await self.transport.send_message(client_id, self._message("system", {"event": "connected", "client_id": client_id}))

    async def _on_client_disconnect(self, client_id: str) -> None:
        with self.registry_lock:
            saved_channels = self.client_channels.pop(client_id, set())
            for channel in saved_channels:
                subscribers = self.channels.get(channel)
                if subscribers is not None:
                    subscribers.discard(client_id)
                    if not subscribers: self.channels.pop(channel, None)
        await self._save_client_state(client_id, "disconnected", saved_channels)

    async def _save_client_state(self, client_id: str, status: str,
                                 channels: set[str]) -> None:
        if self.redis is None:
            return
        await self.redis.hset(
            f"notifications:client:{client_id}",
            mapping={"status": status, "channels": json.dumps(sorted(channels)),
                     "updated_at": timestamp()},
        )

    async def _handle_message(self, sender_id: str, raw_message: str) -> None:
        try: message = json.loads(raw_message)
        except (TypeError, json.JSONDecodeError): return
        if not isinstance(message, dict): return
        message_type, payload = message.get("type"), message.get("payload", {})
        if message_type not in SUPPORTED_TYPES or not isinstance(payload, dict): return
        if message_type not in {"subscribe", "unsubscribe"} and not await self._allow_message(sender_id):
            await self.transport.send_message(
                sender_id,
                self._message("error", {"error": "rate limit exceeded"}),
            )
            return
        channel = message.get("channel", payload.get("channel"))
        if message_type in {"subscribe", "unsubscribe"}:
            if not isinstance(channel, str) or not channel: return
            with self.registry_lock:
                subscribed = self.client_channels.setdefault(sender_id, set())
