        now = asyncio.get_running_loop().time()
        if self.rate_limit == 0:
            return False
        if self.redis is not None:
            try:
                key = f"notifications:rate:{client_id}"
                count = await self.redis.incr(key)
                if count == 1:
                    await self.redis.expire(key, 60)
